<script setup lang="ts">
import { errorMessage } from '@/utils'
import { onMounted,ref } from 'vue'
import {useProjectStore} from '@/stores/project'
import ProjectDialog from './ProjectDialog.vue'
import { type ProjectItem } from '@/types/project'
const store=useProjectStore();onMounted(()=>void store.refresh())
const props=defineProps<{item:ProjectItem}>(),emit=defineEmits<{close:[];saved:[]}>()
const model=ref({name:props.item.name,summary:props.item.summary,category:props.item.category,source:props.item.source,state:props.item.state,group:props.item.group,pinned:props.item.pinned,notes:props.item.notes,defaultEntryId:props.item.defaultEntryId}),tags=ref(props.item.tags.join('，')),busy=ref(false),error=ref('')
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await window.baoyi.project.update(props.item.id,{...model.value,tags:tags.value.split(/[,，]/).map(s=>s.trim()).filter(Boolean)});emit('saved');emit('close')}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
</script>
<template><ProjectDialog :title="$t('编辑项目')" :busy="busy" @close="emit('close')"><form id="project-edit" class="pj-form" @submit.prevent="save"><label class="pj-field">{{ $t("项目名称") }}<input v-model="model.name" required maxlength="160"/></label><label class="pj-field">{{ $t("简介") }}<textarea v-model="model.summary" rows="3" maxlength="4000"/></label><div class="pj-form-pair"><label class="pj-field">{{ $t("类型") }}<select v-model="model.category" :aria-label="$t('类型')"><option v-for="c in store.categories" :key="c">{{c}}</option></select></label><label class="pj-field">{{ $t("来源") }}<select v-model="model.source" :aria-label="$t('来源')"><option value="unknown">{{ $t("未标记") }}</option><option value="self">{{ $t("自己建立") }}</option><option value="third-party">{{ $t("第三方项目") }}</option><option value="mixed">{{ $t("混合来源") }}</option></select></label></div><div class="pj-form-pair"><label class="pj-field">{{ $t("状态") }}<select v-model="model.state" :aria-label="$t('状态')"><option value="active">{{ $t("使用中") }}</option><option value="maintaining">{{ $t("维护中") }}</option><option value="paused">{{ $t("已暂停") }}</option><option value="archived">{{ $t("已归档") }}</option></select></label><label class="pj-field">{{ $t("分组") }}<input v-model="model.group" maxlength="100" :placeholder="$t('例如：工作、兴趣、自用工具')"/></label></div><label class="pj-field">{{ $t("标签") }}<input v-model="tags" :placeholder="$t('用逗号分隔')"/></label><label class="pj-field">{{ $t("默认入口") }}<select v-model="model.defaultEntryId" :aria-label="$t('默认入口')"><option value="">{{ $t("未设置") }}</option><option v-for="e in item.entries" :key="e.id" :value="e.id">{{e.label}}</option></select></label><label class="pj-field">{{ $t("备注") }}<textarea v-model="model.notes" rows="4" maxlength="20000" :placeholder="$t('记录项目用途、注意事项或下次准备做什么…')"/></label><label class="pj-check"><input v-model="model.pinned" type="checkbox"/>{{ $t("置顶这个项目") }}</label><p v-if="error" class="pj-error" role="alert">{{$systemMessage(error)}}</p></form><template #footer><button class="pj-button" :disabled="busy" @click="emit('close')">{{ $t("取消") }}</button><button form="project-edit" class="pj-button pj-primary" :disabled="busy" type="submit">{{ $t("保存") }}</button></template></ProjectDialog></template>
